
'use server';
/**
 * @fileOverview A Genkit flow for deleting a media asset document from Firestore.
 * This flow uses the Firestore REST API to bypass client-side security rules.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';
import { GoogleAuth } from 'google-auth-library';
import { firebaseConfig } from '@/firebase/config';

// Input schema: expects the Firestore document ID of the media asset.
const DeleteMediaAssetInputSchema = z.string();

// Output schema: returns a success status and an optional error message.
const DeleteMediaAssetOutputSchema = z.object({
  success: z.boolean(),
  error: z.string().optional(),
});

/**
 * A server-side function to delete a media asset document from Firestore.
 * This is a wrapper around the Genkit flow.
 * @param mediaId The Firestore document ID of the media asset to delete.
 * @returns A promise that resolves with the result of the deletion.
 */
export async function deleteMediaAsset(
  mediaId: string
): Promise<z.infer<typeof DeleteMediaAssetOutputSchema>> {
  return deleteMediaAssetFlow(mediaId);
}

/**
 * A Genkit flow that deletes a Firestore document using the REST API.
 */
const deleteMediaAssetFlow = ai.defineFlow(
  {
    name: 'deleteMediaAssetFlow',
    inputSchema: DeleteMediaAssetInputSchema,
    outputSchema: DeleteMediaAssetOutputSchema,
  },
  async (mediaId) => {
    const projectId = firebaseConfig.projectId;
    if (!projectId) {
      return { success: false, error: 'Google Cloud Project ID is not configured.' };
    }

    if (!mediaId) {
        return { success: false, error: 'Media ID is required.' };
    }

    try {
      // Initialize Google Auth library to get an authenticated client.
      // This will automatically use the application's service account credentials in a Google Cloud environment.
      const auth = new GoogleAuth({
        scopes: 'https://www.googleapis.com/auth/datastore',
      });
      const client = await auth.getClient();

      // Construct the URL for the Firestore REST API.
      const url = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents/media/${mediaId}`;
      
      // Make an authenticated DELETE request.
      const response = await client.request({
        url,
        method: 'DELETE',
      });

      // A successful DELETE request returns a 200 OK status with an empty body.
      if (response.status === 200) {
        return { success: true };
      } else {
        // If the response is not 200, something went wrong.
        const errorText = response.data ? JSON.stringify(response.data) : `Status code: ${response.status}`;
        console.error('Firestore REST API deletion failed:', errorText);
        return { success: false, error: `Failed to delete media asset. ${errorText}` };
      }
    } catch (e: any) {
      console.error('An unexpected error occurred in deleteMediaAssetFlow:', e);
      return {
        success: false,
        error: e.message || 'An unexpected server error occurred.',
      };
    }
  }
);
