
'use server';

import { v2 as cloudinary } from 'cloudinary';

// Configure Cloudinary with environment variables
cloudinary.config({
  cloud_name: process.env.NEXT_PUBLIC_CLOUDINARY_CLOUD_NAME,
  api_key: process.env.CLOUDINARY_API_KEY,
  api_secret: process.env.CLOUDINARY_API_SECRET,
  secure: true,
});

/**
 * Deletes an asset from Cloudinary using its public ID.
 * This is a server action and requires admin privileges to be called.
 * @param publicId The public ID of the asset to delete.
 * @param resourceType The type of the resource ('image', 'video', 'raw').
 * @returns An object indicating success or failure.
 */
export async function deleteCloudinaryAsset(publicId: string, resourceType: 'image' | 'video' | 'raw' = 'image') {
  if (!process.env.CLOUDINARY_API_KEY || !process.env.CLOUDINARY_API_SECRET) {
    console.error('Cloudinary API Key or Secret is not configured.');
    return { success: false, error: 'Server is not configured for Cloudinary operations.' };
  }

  try {
    const result = await cloudinary.uploader.destroy(publicId, {
      resource_type: resourceType,
    });

    if (result.result === 'ok' || result.result === 'not found') {
      // Treat 'not found' as a success since the asset is gone.
      return { success: true };
    } else {
      console.error('Cloudinary deletion failed:', result);
      return { success: false, error: result.result || 'Failed to delete from Cloudinary.' };
    }
  } catch (error: any) {
    console.error('Error deleting Cloudinary asset:', error);
    return { success: false, error: error.message || 'An unexpected error occurred.' };
  }
}
