
'use server';
/**
 * @fileOverview A Genkit flow for reordering project documents in Firestore.
 * This flow uses the Firestore REST API to perform a series of individual PATCH
 * requests to update the 'order' field, bypassing client-side security rules
 * and avoiding complex batchWrite authentication issues.
 */

import { ai } from '@/ai/genkit';
import { z } from 'zod';
import { GoogleAuth } from 'google-auth-library';
import { firebaseConfig } from '@/firebase/config';

// Input schema: expects an array of document IDs in the desired order.
const ReorderProjectsInputSchema = z.array(z.string());

// Output schema: returns a success status and an optional error message.
const ReorderProjectsOutputSchema = z.object({
  success: z.boolean(),
  error: z.string().optional(),
});

/**
 * A server-side function to reorder projects in Firestore.
 * @param orderedIds An array of project document IDs in the new order.
 * @returns A promise that resolves with the result of the operation.
 */
export async function reorderProjects(
  orderedIds: string[]
): Promise<z.infer<typeof ReorderProjectsOutputSchema>> {
  return reorderProjectsFlow(orderedIds);
}

/**
 * A Genkit flow that reorders Firestore documents using a series of
 * individual PATCH requests via the REST API.
 */
const reorderProjectsFlow = ai.defineFlow(
  {
    name: 'reorderProjectsFlow',
    inputSchema: ReorderProjectsInputSchema,
    outputSchema: ReorderProjectsOutputSchema,
  },
  async (orderedIds) => {
    const projectId = firebaseConfig.projectId;
    if (!projectId) {
      return { success: false, error: 'Google Cloud Project ID is not configured.' };
    }

    if (!orderedIds || orderedIds.length === 0) {
      return { success: true }; // Nothing to do
    }

    try {
      const auth = new GoogleAuth({
        scopes: 'https://www.googleapis.com/auth/datastore',
      });
      const client = await auth.getClient();

      // Create an array of promises for each individual update request.
      const updatePromises = orderedIds.map((id, index) => {
        const url = `https://firestore.googleapis.com/v1/projects/${projectId}/databases/(default)/documents/projects/${id}?updateMask.fieldPaths=order`;

        return client.request({
          url,
          method: 'PATCH',
          data: {
            fields: {
              order: { integerValue: index.toString() },
            },
          },
        });
      });

      // Execute all update promises concurrently.
      const results = await Promise.allSettled(updatePromises);

      // Check if any of the requests failed.
      const failedRequests = results.filter(result => result.status === 'rejected');

      if (failedRequests.length > 0) {
        const firstError = failedRequests[0] as PromiseRejectedResult;
        console.error('One or more Firestore PATCH requests failed:', firstError.reason);
        const errorMessage = firstError.reason?.response?.data?.error?.message || firstError.reason?.message || 'An unexpected error occurred during one of the updates.';
        return { success: false, error: `Failed to reorder projects. ${errorMessage}` };
      }

      return { success: true };

    } catch (e: any) {
      console.error('An unexpected error occurred in reorderProjectsFlow:', e);
      const errorMessage = e.response?.data?.error?.message || e.message || 'An unexpected server error occurred.';
      return {
        success: false,
        error: errorMessage,
      };
    }
  }
);
